import XCTest
@testable import FrenchCore

/// Checks the files the app ships with, as generated by `tools/`.
final class BundledDataTests: XCTestCase {
    private static let resources = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("App/Resources")

    private func load(_ name: String) throws -> Data {
        try Data(contentsOf: Self.resources.appendingPathComponent(name))
    }

    func testContentDecodesAndIsConsistent() throws {
        let content = try Content.decode(load("content.json"))
        XCTAssertGreaterThanOrEqual(content.lessons.count, 15)
        XCTAssertEqual(Set(content.entries.map(\.id)).count, content.entries.count, "card ids must be unique")

        let ruleIDs = Set(content.lessons.flatMap(\.rules).map(\.id))
        for reading in content.readingRules { XCTAssertTrue(ruleIDs.contains(reading.rule), "reading rule points to missing rule \(reading.rule)") }

        for lesson in content.lessons {
            XCTAssertFalse(lesson.topic.isEmpty, "lesson \(lesson.id) has no topic")
            XCTAssertFalse(lesson.words.isEmpty, "lesson \(lesson.id) has no words")
            for word in lesson.words {
                guard let marked = word.m else { continue }
                XCTAssertEqual(Markup.plain(marked), word.fr, "marks change the spelling in lesson \(lesson.id)")
            }
            for case .sentence(let sentence) in lesson.sections.flatMap(\.items) {
                XCTAssertFalse(sentence.tokens.isEmpty)
                for token in sentence.tokens {
                    XCTAssertFalse(token.plain.isEmpty)
                    if let rule = token.rule { XCTAssertTrue(content.readingRules.indices.contains(rule)) }
                }
            }
        }
    }

    /// The three phrases the prototype's reader knew, with the marks typed there by hand.
    func testReaderReproducesThePrototypeSamples() throws {
        let reader = Reader(lexicon: Lexicon(forms: try load("lexicon.tsv"), lemmas: try load("lemmas.tsv")))
        let samples = [
            ("Les enfants habitent à Paris.", "Le{s}‿[en]f[an](ts) (h)abit(ent) à Pari(s).", "le z‿ɑ̃fɑ̃ abit a paʁi"),
            ("Ils ont beaucoup de temps.", "Il{s}‿[on](t) beaucou(p) de t[em](ps).", "il z‿ɔ̃ boku də tɑ̃"),
            ("Vous êtes très aimables.", "Vou{s}‿êt(es) trè{s}‿aimabl(es).", "vu z‿ɛt tʁɛ z‿ɛmabl"),
        ]
        for (phrase, marked, ipa) in samples {
            let words = reader.read(phrase)
            XCTAssertEqual(words.marked, marked)
            XCTAssertEqual(words.ipa, ipa)
        }
    }

    /// The reader links rules with marks and sounds only; the importer had letters aligned with
    /// sounds. On the lesson texts both must agree almost everywhere.
    func testReaderLinksTheSameRulesAsTheLessonTexts() throws {
        let content = try Content.decode(load("content.json"))
        var compared = 0
        var agreed = 0
        for lesson in content.lessons {
            for case .sentence(let sentence) in lesson.sections.flatMap(\.items) {
                for (index, token) in sentence.tokens.enumerated() {
                    guard let marked = token.marked else { continue }
                    let previous = index > 0 ? sentence.tokens[index - 1].marked : nil
                    let subject = RuleSubject(marked: marked, ipa: token.ipa ?? "", link: token.link ?? "", isTied: token.isTied, previous: previous)
                    compared += 1
                    if content.readingRule(for: subject) == token.rule { agreed += 1 }
                }
            }
        }
        XCTAssertGreaterThan(compared, 1000)
        XCTAssertGreaterThanOrEqual(Double(agreed) / Double(compared), 0.95, "\(agreed) of \(compared) words agree")
    }

    func testReaderFindsTheRulesOfASamplePhrase() throws {
        let content = try Content.decode(load("content.json"))
        let reader = Reader(lexicon: Lexicon(forms: try load("lexicon.tsv"), lemmas: try load("lemmas.tsv")))
        let labels = content.rulesApplying(to: reader.read("Les enfants habitent à Paris.").ruleSubjects.map(\.subject)).map(\.rule.label)
        XCTAssertTrue(labels.contains("Связывание"), "\(labels)")
        XCTAssertTrue(labels.contains("Носовые гласные"), "\(labels)")
        XCTAssertTrue(labels.contains("Буква h"), "\(labels)")
        XCTAssertTrue(labels.contains { $0.hasPrefix("s на конце") }, "\(labels)")
    }

    func testExamplesFileHasLessonPhrasesFirst() throws {
        let examples = Examples(data: try load("examples.tsv"))
        let ami = try examples.of(lemma: "ami")
        XCTAssertEqual(ami.first?.lesson.map { $0 > 0 }, true)
        XCTAssertTrue(ami.contains { $0.lesson == nil }, "Tatoeba sentences follow the lesson phrases")
    }

    /// Every rule of the lessons can be found in a phrase: a trigger of its own, or items of
    /// «Правила чтения»; notes aside.
    func testEveryRuleCanBeFoundInAPhrase() throws {
        let content = try Content.decode(load("content.json"))
        let itemized = Set(content.readingRules.map(\.rule))
        for rule in content.lessons.flatMap(\.rules) where rule.kind != "Примечания" {
            XCTAssertTrue(rule.trigger != nil || itemized.contains(rule.id), "\(rule.id) «\(rule.title)» can never be shown")
        }
    }

    func testGrammarRulesOfSamplePhrases() throws {
        let content = try Content.decode(load("content.json"))
        let lexicon = Lexicon(forms: try load("lexicon.tsv"), lemmas: try load("lemmas.tsv"))
        let reader = Reader(lexicon: lexicon)
        func ids(_ phrase: String) -> Set<String> {
            Set(content.rulesTriggered(by: reader.read(phrase), lexicon: lexicon).map(\.rule.id))
        }
        let negation = ids("Je ne vais pas au cinéma.")
        XCTAssertTrue(negation.isSuperset(of: ["5-10", "9-3", "13-4"]), "ne… pas, au, aller: \(negation.sorted())")
        let table = ids("Il y a du pain sur la table.")
        XCTAssertTrue(table.isSuperset(of: ["13-3", "8-5"]), "il y a, du: \(table.sorted())")
        XCTAssertFalse(table.contains("9-5"), "la table: an article, not the pronoun la")
        XCTAssertFalse(table.contains("3-3"), "table is a noun here, not a verb of group I")
        XCTAssertTrue(ids("Je n'ai pas de frère.").contains("15-3"))
        XCTAssertTrue(ids("Lucie est Russe.").contains("7-4"))
        XCTAssertTrue(ids("Qu'est-ce que tu fais ?").isSuperset(of: ["7-5", "8-3", "14-6", "7-3"]))
        XCTAssertTrue(ids("Je ne vais pas au cinéma.").contains("11-1") == false, "no [ɔ̃] in the phrase")
    }

    func testReferenceAndGlossary() throws {
        let book = try ReferenceBook.decode(load("reference.json"))
        XCTAssertEqual(book.categories.first?.title, "Предлоги")
        for category in book.categories { XCTAssertGreaterThanOrEqual(category.words.count, 5, category.title) }
        let prepositions = try XCTUnwrap(book.categories.first)
        XCTAssertGreaterThan(prepositions.gaps?.count ?? 0, 50)
        for gap in prepositions.gaps ?? [] {
            XCTAssertTrue(prepositions.words.contains { $0.fr.lowercased() == gap.answer.lowercased() }, "\(gap.answer) is a preposition of the list")
        }
        let glossary = Glossary(data: try load("dictionary.tsv"))
        XCTAssertEqual(glossary.info(of: "ami")?.level, "A1")
        XCTAssertNotNil(glossary.info(of: "voiture")?.translation)
    }

    func testEveryLessonWordWithFormsHasAParadigm() throws {
        let lexicon = Lexicon(forms: try load("lexicon.tsv"), lemmas: try load("lemmas.tsv"))
        let grammar = Grammar(lexicon: lexicon)
        XCTAssertEqual(grammar.analyses(of: "buvons").first?.analysis.lemma, "boire")
        XCTAssertEqual(grammar.analyses(of: "petites").first?.analysis.lemma, "petit")
        let boire = try XCTUnwrap(grammar.paradigm(lemma: "boire", as: .verb))
        XCTAssertEqual(boire.sets.map(\.name), Grammar.tenseNames)
        XCTAssertEqual(boire.sets[0].forms.map(\.marked), ["je boi(s)", "tu boi(s)", "il boi(t)", "nou(s) buv[on](s)", "vou(s) buve(z)", "il(s) boiv(ent)"])
    }
}
